export function Translation({
  sourceText = "{{sourceText}}",
  targetLang = "{{targetLang}}",
  reviewedByHuman = {{reviewedByHuman}},
  accent = "{{accent}}",
}) {
  const outputs = { es: "ES: Gracias por tu pedido", fr: "FR: Merci pour votre commande", de: "DE: Danke f\u00FCr Ihre Bestellung" };
  return (
    <div style={{ font: "14px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p lang="en" style={{ margin: "0 0 10px", padding: "10px 12px", borderRadius: 8, background: "#24143010", fontSize: 13 }}>EN: {sourceText}</p>
      <p lang={targetLang} style={{ margin: "0 0 12px", padding: "10px 12px", borderRadius: 8, background: "#ffffff", border: "1px solid #24143018", fontSize: 13, fontWeight: 600 }}>{outputs[targetLang]}</p>
      <span style={{ display: "inline-block", fontSize: 10, fontWeight: 700, padding: "3px 9px", borderRadius: 999, color: "#241430", background: accent }}>{reviewedByHuman ? "Human-reviewed" : "Machine translation"}</span>
    </div>
  );
}
